require 'config.php'; require 'auth.php'; requireLogin(); $pageTitle='Edit Alat'; $id=(int)($_GET['id']??0);$items=read_data('items');$idx=find_index($items,$id);if($idx===null){$_SESSION['flash']=['type'=>'error','message'=>'Alat tidak ditemukan.'];redirect('index.php');}$item=$items[$idx];$categories=read_data('categories');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$unit=trim($_POST['unit']??'')?:'pcs';$min=max(0,(int)($_POST['min_stock']??0));if($sku===''||$name==='')$errors[]='Kode dan nama wajib diisi.';elseif(array_filter($items,fn($i)=>$i['id']!=$id&&strcasecmp($i['sku'],$sku)===0))$errors[]='Kode alat sudah digunakan.';else{$items[$idx]=array_merge($items[$idx],['sku'=>$sku,'name'=>$name,'category_id'=>$cat?:null,'unit'=>$unit,'min_stock'=>$min]);write_data('items',$items);$_SESSION['flash']=['type'=>'success','message'=>'Alat berhasil diperbarui.'];redirect('index.php');}}else $_POST=$item;include 'header.php'; ?>
<section class="page-heading"><div><h1>Edit Alat</h1></div></section><div class="form-card"><?php foreach($errors as $x):?><div class="alert alert-error"><?=e($x)?></div><?php endforeach;?><form method="post"><div class="form-group"><label>Kode</label><input name="sku" value="<?=e($_POST['sku'])?>" required></div><div class="form-group"><label>Nama</label><input name="name" value="<?=e($_POST['name'])?>" required></div><div class="form-group"><label>Kategori</label><select name="category_id"><option value="">Tanpa kategori</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($c['id']==($_POST['category_id']??0))?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Satuan</label><input name="unit" list="unit-list" value="<?=e($_POST['unit'])?>" placeholder="Pilih atau ketik satuan baru"><datalist id="unit-list"><option value="pcs"><option value="meter"><option value="box"><option value="roll"><option value="pack"><option value="unit"><option value="set"><option value="liter"><option value="kg"></datalist></div><div class="form-group"><label>Stok Saat Ini</label><input value="<?=e($item['stock'])?>" disabled></div><div class="form-group"><label>Batas Stok Menipis</label><input type="number" name="min_stock" min="0" value="<?=e($_POST['min_stock'])?>"></div><div class="form-actions"><button class="btn btn-primary">Update</button><a class="btn btn-secondary" href="index.php">Batal</a></div></form></div><?php include 'footer.php'; ?>